	data = this.validatedata(mode, data)
	if (data === null) {
		throw new Error('invalid data format')
	}
	if (ecclevel < 0 || ecclevel > 3) {
		throw new Error('invalid ECC level')
	}
	if (ver < 0) {
		for (ver = 1; ver <= 40; ++ver) {
			if (data.length <= this.getmaxdatalen(ver, mode, ecclevel)) {
				break
			}
		}
		if (ver > 40) {
			throw new Error('too large data')
		}
	} else if (ver < 1 || ver > 40) {
		throw new Error('invalid version')
	}
	if (mask !== -1 && (mask < 0 || mask > 8)) {
		throw new Error('invalid mask')
	}
	return this.generateMatrix(data, ver, mode, ecclevel, mask)
}


quartzrabbit.generateSVG = async function (data, options) {
	options = options || {}
	let fillcolor = options.fillcolor ? options.fillcolor : {
		type: COLOR_TYPES.SIMPLE,
		color: '#FFFFFF'
	}
	let textcolor = options.textcolor ? options.textcolor : {
		type: COLOR_TYPES.SIMPLE,
		color: '#000000'
	}
	let rounded = options.rounded ? options.rounded : false
	let logo = (options.logo && (options.logo.path || options.logo.svgString)) ? options.logo : false
	let logoSize = (options.logo && options.logo.size) ? Math.max(Math.min(options.logo.size, 0.8), 0.1) : 0.2
	let matrix = this.generate(data, options)
	let n = matrix.length
	let modsize = Math.max(options.modulesize || 5, 0.5)
	let margin = Math.max(options.margin ? options.margin : 4, 0.0)
	let sizeOfSVG = modsize * (n + 2 * margin)

	let eyeTL = {
		borderType: EYE_TYPES.RECTANGULAR,
		borderColor: false,
		eyeType: EYE_TYPES.RECTANGULAR,
		eyeColor: false
	}
	let eyeTR = {
		borderType: EYE_TYPES.RECTANGULAR,
		borderColor: false,
		eyeType: EYE_TYPES.RECTANGULAR,
		eyeColor: false
	}
	let eyeBL = {
		borderType: EYE_TYPES.RECTANGULAR,
		borderColor: false,
		eyeType: EYE_TYPES.RECTANGULAR,
		eyeColor: false
	}

	if (options.eyes && options.eyes.eyeTL) {
		eyeTL.borderType = options.eyes.eyeTL.borderType || EYE_TYPES.RECTANGULAR
		eyeTL.eyeType = options.eyes.eyeTL.eyeType || EYE_TYPES.RECTANGULAR
		eyeTL.eyeColor = options.eyes.eyeTL.eyeColor || false
		eyeTL.borderColor = options.eyes.eyeTL.borderColor || false
	}
	if (options.eyes && options.eyes.eyeTR) {
		eyeTR.borderType = options.eyes.eyeTR.borderType || EYE_TYPES.RECTANGULAR
		eyeTR.eyeType = options.eyes.eyeTR.eyeType || EYE_TYPES.RECTANGULAR
		eyeTR.eyeColor = options.eyes.eyeTR.eyeColor || false
		eyeTR.borderColor = options.eyes.eyeTR.borderColor || false
	}
	if (options.eyes && options.eyes.eyeBL) {
		eyeBL.borderType = options.eyes.eyeBL.borderType || EYE_TYPES.RECTANGULAR
		eyeBL.eyeType = options.eyes.eyeBL.eyeType || EYE_TYPES.RECTANGULAR
		eyeBL.eyeColor = options.eyes.eyeBL.eyeColor || false
		eyeBL.borderColor = options.eyes.eyeBL.borderColor || false
	}

	matrix = this.removeEyesFromMatrix(matrix)

	let createGradient = function (el, id, gradientOptions) {
		let elName = 'linearGradient'
		let type = gradientOptions.type
		let stops = gradientOptions.stops
		if (type === COLOR_TYPES.RADIAL_GRADIENT) {
			elName = 'radialGradient'
		}
		let gradient = el.append(elName)
		gradient.attr('id', id)
			.attr('gradientUnits', 'userSpaceOnUse')
		if (gradientOptions.spreadMethod) {
			gradient.attr('spreadMethod', gradientOptions.spreadMethod)
		}

		if (type === COLOR_TYPES.LINEAR_GRADIENT && gradientOptions.rotate) {
			gradient.attr('gradientTransform', `rotate(${gradientOptions.rotate})`)
		}

		if (type === COLOR_TYPES.RADIAL_GRADIENT && gradientOptions.cx && gradientOptions.cy) {
			gradient.attr('cx', gradientOptions.cx)
			gradient.attr('cy', gradientOptions.cy)
		}
		if (type === COLOR_TYPES.RADIAL_GRADIENT && gradientOptions.fx && gradientOptions.fy) {
			gradient.attr('fx', gradientOptions.fx)
			gradient.attr('fy', gradientOptions.fy)
		}
		if (type === COLOR_TYPES.RADIAL_GRADIENT && gradientOptions.r) {
			gradient.attr('r', gradientOptions.r)
		}
		if (type === COLOR_TYPES.RADIAL_GRADIENT && gradientOptions.fr) {
			gradient.attr('fr', gradientOptions.fr)
		}

		stops.forEach(stop => {
			gradient.append('stop')
				.attr('offset', stop.offset)
				.attr('stop-color', stop.color)
				.attr('stop-opacity', stop.opacity)
		})
		return gradient
	}

	const d3n = new D3Node()

	// Generate SVG object...
	let obj = d3n.createSVG(sizeOfSVG, sizeOfSVG)

	let qrcodeId = 'qrcode' + Date.now()
	obj.attr('id', qrcodeId)
	// obj.attr('style', 'shape-rendering:crispEdges')
	let defs = obj.append('defs')
	if (fillcolor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'bgGradient', fillcolor)
	}
	if (textcolor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'fgGradient', textcolor)
	}
	if (eyeTL.eyeColor && eyeTL.eyeColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeTLGradient', eyeTL.eyeColor)
	}
	if (eyeTL.borderColor && eyeTL.borderColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeTLBorderGradient', eyeTL.borderColor)
	}
	if (eyeTR.eyeColor && eyeTR.eyeColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeTRGradient', eyeTR.eyeColor)
	}
	if (eyeTR.borderColor && eyeTR.borderColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeTRBorderGradient', eyeTR.borderColor)
	}
	if (eyeBL.eyeColor && eyeBL.eyeColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeBLGradient', eyeBL.eyeColor)
	}
	if (eyeBL.borderColor && eyeBL.borderColor.type !== COLOR_TYPES.SIMPLE) {
		createGradient(defs, 'eyeBLBorderGradient', eyeBL.borderColor)
	}

	let g = obj.append('g')

	let createRect = function (el, className, color, x, y, s, r) {
		let rect = el.append('rect')
		rect.attr('class', className)
		rect.attr('fill', color.color)
		rect.attr('x', x)
		rect.attr('y', y)
		rect.attr('width', s)
		rect.attr('height', s)
		return rect
	}

	let bgColor = {
		type: fillcolor.type,
		attr: 'fill',
		color: (fillcolor.type === COLOR_TYPES.SIMPLE) ? fillcolor.color : 'url(#bgGradient)'
	}
	createRect(g, 'bg', bgColor, 0, 0, sizeOfSVG)

	// createRect(g, "eye", "red", margin * modsize, margin * modsize, modsize * 3, false)


	let fgColor = {
		type: textcolor.type,
		attr: 'mask',
		color: (textcolor.type === COLOR_TYPES.SIMPLE) ? textcolor.color : 'url(#fgGradient)'
	}

	let yo = margin * modsize
	for (let y = 0; y < n; ++y) {
		let xo = margin * modsize
		for (let x = 0; x < n; ++x) {
			if (matrix[y][x]) {
				createRect(g, 'fg', fgColor, xo, yo, modsize, rounded)
			}
			xo += modsize
		}
		yo += modsize
	}

	let createEyeBorder = function (el, className, type, color, x, y, size) {
		let borderSize = 6 * modsize
		let rect = el.append('rect')
		rect.attr('class', className)
		rect.attr('fill', 'none')
		if (!color) {
			rect.attr('stroke', 'url(#fgGradient)')
		} else {
			rect.attr('stroke', (color.type === COLOR_TYPES.SIMPLE) ? color.color : `url(#${className}Gradient`)
		}
		rect.attr('stroke-width', modsize)
		rect.attr('x', x)
		rect.attr('y', y)
		if (type !== EYE_TYPES.RECTANGULAR) {
			rect.attr('rx', (type === EYE_TYPES.CIRCULAR) ? borderSize / 2 : modsize * 2)
			rect.attr('ry', (type === EYE_TYPES.CIRCULAR) ? borderSize / 2 : modsize * 2)
		}
		rect.attr('width', borderSize)
		rect.attr('height', borderSize)
		return rect
	}
	let createEye = function (el, className, type, color, x, y) {
		let size = modsize * 3
		let shift = modsize + modsize / 2
		let rect = el.append('rect')
		rect.attr('class', className)
		if (!color) {
			rect.attr('fill', 'url(#fgGradient)')
		} else {
			rect.attr('fill', (color.type === COLOR_TYPES.SIMPLE) ? color.color : `url(#${className}Gradient`)
		}
		rect.attr('x', x + shift)
		rect.attr('y', y + shift)
		if (type !== EYE_TYPES.RECTANGULAR) {
			rect.attr('rx', (type === EYE_TYPES.CIRCULAR) ? size / 2 : modsize)
			rect.attr('ry', (type === EYE_TYPES.CIRCULAR) ? size / 2 : modsize)
		}
		rect.attr('width', size)
		rect.attr('height', size)
		return rect
	}


	let eyeTLConfig = {
		x: margin * modsize + modsize / 2,
		y: margin * modsize + modsize / 2
	}
	createEyeBorder(g, 'eyeTLBorder', eyeTL.borderType, eyeTL.borderColor, eyeTLConfig.x, eyeTLConfig.y)
	createEye(g, 'eyeTL', eyeTL.eyeType, eyeTL.eyeColor, eyeTLConfig.x, eyeTLConfig.y)

	let eyeTRConfig = {
		x: sizeOfSVG - 6 * modsize - margin * modsize - modsize / 2,
		y: margin * modsize + modsize / 2
	}
	createEyeBorder(g, 'eyeTRBorder', eyeTR.borderType, eyeTR.borderColor, eyeTRConfig.x, eyeTRConfig.y)
	createEye(g, 'eyeTR', eyeTR.eyeType, eyeTR.eyeColor, eyeTRConfig.x, eyeTRConfig.y)
	let eyeBLConfig = {
		x: margin * modsize + modsize / 2,
		y: sizeOfSVG - 6 * modsize - margin * modsize - modsize / 2
	}
	createEyeBorder(g, 'eyeBLBorder', eyeBL.borderType, eyeBL.borderColor, eyeBLConfig.x, eyeBLConfig.y)
	createEye(g, 'eyeBL', eyeBL.borderType, eyeBL.borderColor, eyeBLConfig.x, eyeBLConfig.y)

	let svgString = d3n.svgString()

	if (logo) {
		let logoSVG
		if (logo.path && !logo.svgString) {
			const fs = require('fs')
			logoSVG = fs.readFileSync(logo.path, 'utf8')
		}
		if (logo.svgString) {
			logoSVG = logo.svgString
		}
		let parsedXML = await this.parseXML(logoSVG)

		let maxSizeOfLogo = sizeOfSVG * logoSize
		let calculated = {
			width: 0,
			height: 0,
			x: 0,
			y: 0
		}

		if (parseFloat(parsedXML.svg.$.width) === parseFloat(parsedXML.svg.$.height)) {
			calculated.width = maxSizeOfLogo
			calculated.height = maxSizeOfLogo
		} else {
			let maxMetric = 'width'
			let minMetric = 'height'
			if (parseFloat(parsedXML.svg.$.width) < parseFloat(parsedXML.svg.$.height)) {
				maxMetric = 'height'
				minMetric = 'width'
			}
			let greaterSize = parseFloat(parsedXML.svg.$[maxMetric])
			let aspectRatio = maxSizeOfLogo / greaterSize
			calculated[maxMetric] = maxSizeOfLogo
			calculated[minMetric] = parseFloat(parsedXML.svg.$[minMetric]) * aspectRatio
		}

		calculated.x = sizeOfSVG / 2 - calculated.width / 2
		calculated.y = sizeOfSVG / 2 - calculated.height / 2


		parsedXML.svg.$.width = calculated.width
		parsedXML.svg.$.height = calculated.height
		parsedXML.svg.$.x = calculated.x
		parsedXML.svg.$.y = calculated.y
		let builtXML = this.buildXML(parsedXML)
		svgString = svgString.split('</svg>') + builtXML + '</svg>'
	}


	return svgString
}


module.exports = {
	ECCLEVELS,
	MODES,
	COLOR_TYPES,
